/* From Uiverse.io by alexruix - Tags: minimalist, card, modern, animated */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  position: relative;
  border-radius: 16px;
  background: #f5f5f5;
  transition: box-shadow .3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  overflow: hidden;
  cursor: pointer;
}

.__UIV_SCOPE__ .card-img {
  position: absolute;
  height: 100%;
  width: 100%;
  background-color: #6eee87;
}

.__UIV_SCOPE__ .card-info {
  position: absolute;
  width: 100%;
  bottom: 0;
  padding: 1rem;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.__UIV_SCOPE__ .card-icon {
  opacity: 0;
  transform: translateX(-20%);
  width: 2em;
  height: 2em;
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ .icon {
  --size: 20px;
  width: var(--size);
  height: var(--size);
}

/*Text*/
.__UIV_SCOPE__ .card-text p {
  line-height: 140%;
 /*Delete this line for multi-line text*/
  white-space: nowrap;
}

.__UIV_SCOPE__ .text-title {
  font-weight: 900;
  font-size: 1.2rem;
  color: #222;
}

.__UIV_SCOPE__ .text-subtitle {
  color: #333;
  font-weight: 500;
  font-size: 1rem;
}

/*Hover*/
.__UIV_SCOPE__ .card:hover {
  box-shadow: 0 10px 20px 4px rgba(35, 35, 35, .1);
}

.__UIV_SCOPE__ .card:hover .card-icon {
  opacity: 1;
  transform: translateX(20%);
}
